private void processTask(Long taskId) {
    // 只有「未处理」的任务才允许执行，防止重复消费
    if (!Objects.equals(entity.getTaskStatus(), MdMultimediaTaskStatusEnum.NO_PROCESS.getCode())) {
        log.error("processTask-任务状态不是未处理{}", taskId);
        return;
    }
    entity = this.updateTaskStatus(entity, MdMultimediaTaskStatusEnum.PROCESS_ING.getCode());
    String taskResult = null;
    Integer taskDuration = null;
    try {
        String taskType = entity.getTaskType();
        String taskInfo = entity.getTaskInfo();
        if (Objects.equals(taskType, MultimediaTaskTypeEnum.FORMAT_CONVERT_MP4_TO_HLS.toString())) {
            VideoHandleResultDTO dto = ffmpegService.getVedioHlsUrl(taskInfo, false);
            taskResult = dto != null ? dto.getHlsUrl() : null;
            // 时长随转码结果一并带回，落库并通过完成消息透传
            taskDuration = dto != null ? dto.getDuration() : null;
        } else if (Objects.equals(taskType, MultimediaTaskTypeEnum.SCREEN_SHOTS_COVER.toString())) {
            taskResult = ffmpegService.getCoverFromVideo(taskInfo);
        }
    } catch (Exception e) {
        this.taskProcessException(entity);
        return;
    }
    if (StringUtils.isBlank(taskResult)) {
        this.taskProcessException(entity);
        return;
    }
    this.taskProcessComplete(entity, taskResult, taskDuration);
}

private Integer getVideoDurationSeconds(String videoRemoteUrl) {
    try {
        VideoBasicInfo info = getBitrate(videoRemoteUrl);
        String duration = info == null ? null : info.getDuration();
        if (StringUtil.isBlank(duration)) {
            return null;
        }
        return (int) Math.round(Double.parseDouble(duration));
    } catch (Exception e) {
        log.info("get video duration failed. videoRemoteUrl: {}", videoRemoteUrl, e);
        return null;
    }
}

