private void formatConvertHandler(String businessId, String taskInfo,
                                  String taskResult, Integer taskDuration) {
    if (StringUtils.isBlank(businessId)) {
        return;
    }
    DocumentInfoEntity entity = queryVideoDocument(Long.valueOf(businessId));
    if (Objects.isNull(entity)) {
        return;
    }
    if (isStaleTaskMessage(taskInfo, entity)) {
        return;
    }
    entity.setVideoHlsUrl(taskResult);
    entity.setDuration(taskDuration);
    entity.setProcessState(PROCESS_STATE_SUCCESS);
    documentInfoDao.save(entity);
}

private boolean isStaleTaskMessage(String taskInfo, DocumentInfoEntity entity) {
    if (StringUtils.isBlank(taskInfo)) {
        return false;
    }
    String taskJfrogPath = new String(Base64Utils.decode(taskInfo.getBytes()));
    if (!StringUtils.equals(taskJfrogPath, entity.getJfrogPath())) {
        log.warn("stale task message dropped, id: {}, taskPath: {}, entityPath: {}",
                entity.getId(), taskJfrogPath, entity.getJfrogPath());
        return true;
    }
    return false;
}
